def best_shifts(pay):
    before, last = [0, 0], [0, 0]
    for x in pay:
        take = [before[0] + x, before[1] + 1]
        before, last = last, (take if take[0] >= last[0] else last)
    return last

def best_shifts(pay):
    even, odd = pay[0::2], pay[1::2]
    if sum(odd) > sum(even):
        return [sum(odd), sum(1 for x in odd if x)]
    return [sum(even), sum(1 for x in even if x)]

def best_shifts(pay):
    n = len(pay)
    used = [False] * (n + 2)
    total = days = 0
    for i in sorted(range(n), key=lambda i: -pay[i]):
        if pay[i] and not used[i] and not used[i + 2]:
            used[i + 1] = True
            total += pay[i]
            days += 1
    return [total, days]
